import os
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

os.environ["CXX"] = "hipcc"

# Fused kernel: tanh(softplus(x)) * x + batchnorm
# Combines all element-wise operations into a single kernel
fused_activation_bn_cpp_source = """
#include <hip/hip_runtime.h>
#include <hip/hip_fp16.h>

#define TILE_SIZE 16

__device__ __forceinline__ float softplus(float x) {
    return logf(1.0f + expf(x));
}

__global__ void fused_activation_bn_kernel(
    const float* __restrict__ x,
    float* __restrict__ out,
    const float* __restrict__ gamma,
    const float* __restrict__ beta,
    const float* __restrict__ running_mean,
    const float* __restrict__ running_var,
    float eps,
    int n, int c, int h, int w)  // n=batch, c=channels, h=height, w=width
{
    int batch = blockIdx.z;
    int ch = blockIdx.y;

    int y = blockIdx.x * TILE_SIZE + threadIdx.y;
    int x = blockIdx.x * TILE_SIZE + threadIdx.x;

    if (y < h && x < w) {
        int idx = batch * c * h * w + ch * h * w + y * w + x;

        float val = x[idx];
        // Softplus: log(1 + exp(x)), numerically stable version
        float sp = softplus(val);
        // Tanh: tanh(val)
        float th = tanhf(sp);
        // Element-wise multiply
        float activated = th * val;

        // BatchNorm: (x - mean) / sqrt(var + eps) * gamma + beta
        float mean = running_mean[ch];
        float var = running_var[ch];
        float gm = gamma[ch];
        float bt = beta[ch];

        out[idx] = gm * (activated - mean) / sqrtf(var + eps) + bt;
    }
}

torch::Tensor fused_activation_bn_hip(
    torch::Tensor x,
    torch::Tensor gamma,
    torch::Tensor beta,
    torch::Tensor running_mean,
    torch::Tensor running_var,
    double eps) {

    int n = x.size(0);  // batch
    int c = x.size(1);  // channels
    int h = x.size(2);  // height
    int w = x.size(3);  // width

    auto out = torch::empty_like(x);

    dim3 block(TILE_SIZE, TILE_SIZE);
    dim3 grid((w + TILE_SIZE - 1) / TILE_SIZE, c, n);

    fused_activation_bn_kernel<<<grid, block>>>(
        x.data_ptr<float>(),
        out.data_ptr<float>(),
        gamma.data_ptr<float>(),
        beta.data_ptr<float>(),
        running_mean.data_ptr<float>(),
        running_var.data_ptr<float>(),
        eps,
        n, c, h, w
    );

    return out;
}
"""

fused_activation_bn = load_inline(
    name="fused_activation_bn",
    cpp_sources=fused_activation_bn_cpp_source,
    functions=["fused_activation_bn_hip"],
    verbose=True,
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, eps=1e-5, momentum=0.1):
        super(ModelNew, self).__init__()
        # Keep conv2d as is (already optimized)
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size)
        # Use PyTorch.BatchNorm2d for storing running stats, but use custom kernel in forward
        self.bn = nn.BatchNorm2d(out_channels, eps=eps, momentum=momentum)
        self.fused_activation_bn = fused_activation_bn

    def forward(self, x):
        x = self.conv(x)
        # Use fused kernel for activation + batchnorm
        x = self.fused_activation_bn.fused_activation_bn_hip(
            x, 
            self.bn.weight, 
            self.bn.bias, 
            self.bn.running_mean, 
            self.bn.running_var, 
            self.bn.eps
        )
        return x

